//! A JAM network whose chain spec is generated by the node's own `gen-spec`, instead of being
//! built in process (the default, covered by `jam-smoke-native`).
//!
//! Needs `polkajam` in `PATH`.

use std::time::{Duration, Instant};

use anyhow::Context;
use configuration::{NetworkConfig, NetworkConfigBuilder};
use serde_json::Value;
use subxt::ext::jsonrpsee::rpc_params;
use zombienet_sdk::{
    environment::get_spawn_fn, subxt::ext::jsonrpsee::core::client::ClientT, JamNetworkNode,
};

pub const DEADLINE: Duration = Duration::from_secs(5 * 60);

fn small_network() -> NetworkConfig {
    NetworkConfigBuilder::new()
        .with_jamchain(|jamchain| {
            let mut jamchain = jamchain
                .with_id("dev")
                .with_chain_spec_command("polkajam")
                .with_validator(|n| n.with_name("jam0"));
            for i in 1..6 {
                jamchain = jamchain.with_validator(|n| n.with_name(&format!("jam{i}")));
            }
            jamchain.with_ordinary(|n| n.with_name("jam-or"))
        })
        .build()
        .unwrap()
}

/// Wait until the node reports a synced chain that has moved past genesis.
async fn wait_ready(node: &JamNetworkNode, deadline: Instant) -> anyhow::Result<()> {
    let client = node.wait_client_with_timeout(60_u64).await?;
    while Instant::now() < deadline {
        let sync_state: Value = client
            .request("syncState", rpc_params![])
            .await
            .context("syncState")?;
        let block: Value = client
            .request("finalizedBlock", rpc_params![])
            .await
            .context("finalizedBlock")?;
        let slot = block["slot"].as_u64().unwrap_or(0);

        if sync_state["status"] == "Completed" && slot > 0 {
            return Ok(());
        }
        tokio::time::sleep(Duration::from_secs(2)).await;
    }

    Err(anyhow::anyhow!(
        "[{}] did not finalize a block in time",
        node.name()
    ))
}

#[tokio::test(flavor = "multi_thread")]
async fn ci_native_smoke_with_gen_spec_should_works() {
    tracing_subscriber::fmt::init();

    let network = get_spawn_fn()(small_network()).await.unwrap();

    let deadline = Instant::now() + DEADLINE;
    let rpc_node = network
        .get_jam_node("jam-or")
        .expect("jam-or should be present");
    wait_ready(rpc_node, deadline)
        .await
        .expect("wait_ready state");
}
